const input = $input.first().json;
const body = input.body ?? input;

const sessionId = (body.sessionId || '').toString().trim();
const rawMessage = (body.message || '').toString().trim();

const errors = [];
if (!sessionId) errors.push('sessionId es obligatorio.');
if (!rawMessage) errors.push('message no puede estar vacío.');
if (rawMessage.length > 4000) errors.push('message supera el máximo de 4000 caracteres.');

let rateLimited = false;
const data = $getWorkflowStaticData('global');
if (!data.rateLimit) data.rateLimit = {};

if (errors.length === 0) {
  const WINDOW_MS = 60000;
  const MAX_REQUESTS = 10;
  const now = Date.now();
  const bucket = (data.rateLimit[sessionId] || []).filter((t) => now - t < WINDOW_MS);

  if (bucket.length >= MAX_REQUESTS) {
    rateLimited = true;
    errors.push('Has enviado demasiados mensajes. Espera un minuto antes de volver a intentar.');
  } else {
    bucket.push(now);
    data.rateLimit[sessionId] = bucket;
  }
}

return [{
  json: {
    isValid: errors.length === 0,
    rateLimited,
    errorMessage: errors.join(' '),
    sessionId,
    message: rawMessage,
  },
}];

const sessionId = $json.sessionId;
const message = (($json.message || '').toString()).toLowerCase();

const RULES = [
  {
    test: /hola|buenas|hey|qué tal|buenos días|buenas tardes|buenas noches/,
    reply: '¡Hola! Soy el asistente virtual de SION, la plataforma de inscripción de la Universidad Adventista de Colombia. Puedo ayudarte con dudas sobre el proceso de inscripción, los documentos que necesitas o el pago del derecho de inscripción.',
  },
  {
    test: /documento|icfes|diploma|bachiller|adjuntar|subir/,
    reply: 'Para inscribirte necesitas tres documentos: tu documento de identidad, los resultados del examen ICFES y tu diploma de bachiller. Los adjuntas directamente en la plataforma, en el último paso del formulario de inscripción.',
  },
  {
    test: /inscrib|proceso|pasos|formulario|wizard/,
    reply: 'El proceso de inscripción tiene tres pasos: datos personales, el programa académico al que aspiras, y tus documentos. Puedes guardar tu avance en cualquier momento y continuar después. Una vez la envías, un administrador la revisa.',
  },
  {
    test: /pago|recibo|tarifa|valor|cuesta|precio/,
    reply: 'Al enviar tu inscripción se genera un recibo con el valor del derecho de inscripción del periodo vigente y una fecha límite de pago. Encuentras el detalle exacto dentro de tu cuenta, en la sección de tu recibo.',
  },
  {
    test: /estado|aprobad|rechazad|resultado|como voy/,
    reply: 'Puedes consultar el estado de tu inscripción iniciando sesión en la plataforma. Si fue aprobada, pasas automáticamente a ser estudiante; si fue rechazada, verás el motivo y podrás corregirla y reenviarla.',
  },
  {
    test: /entrevista/,
    reply: 'Según el programa al que aspires, puede haber una entrevista de admisión antes de la decisión final. Si te corresponde, verás la fecha y la modalidad (presencial o virtual) dentro de tu cuenta.',
  },
  {
    test: /estudiante|promovid|ya soy/,
    reply: 'Solo se llega a ser estudiante cuando un administrador aprueba tu inscripción; ese paso promueve tu cuenta automáticamente, no necesitas hacer nada adicional.',
  },
  {
    test: /gracias|listo|ok[,.]?$/,
    reply: '¡Con gusto! Si tienes otra pregunta sobre tu inscripción, aquí estoy.',
  },
];

const match = RULES.find((rule) => rule.test.test(message));
const reply = match
  ? match.reply
  : 'Gracias por tu mensaje. Soy el asistente virtual de SION y puedo ayudarte con preguntas sobre el proceso de inscripción, los documentos requeridos, el pago o el estado de tu solicitud. ¿Sobre cuál te gustaría saber más?';

return [{
  json: {
    success: true,
    sessionId,
    reply,
    timestamp: new Date().toISOString(),
  },
}];

const { sessionId, message } = $json;
const MAX_TURNS = 20;

const data = $getWorkflowStaticData('global');
if (!data.conversations) data.conversations = {};
if (!data.conversations[sessionId]) data.conversations[sessionId] = [];

const history = data.conversations[sessionId].slice(-MAX_TURNS);

const contents = history.map((turn) => ({
  role: turn.role,
  parts: [{ text: turn.text }],
}));

contents.push({ role: 'user', parts: [{ text: message }] });

return [{
  json: {
    sessionId,
    message,
    contents,
  },
}];

const sessionId = $('Code - Construir historial').item.json.sessionId;
const message = $('Code - Construir historial').item.json.message;
const response = $input.first().json;

const reply = response?.candidates?.[0]?.content?.parts?.map((p) => p.text).join('')
  ?? 'No se obtuvo una respuesta del modelo. Intenta reformular tu pregunta.';

const data = $getWorkflowStaticData('global');
const history = data.conversations[sessionId];
history.push({ role: 'user', text: message });
history.push({ role: 'model', text: reply });

const MAX_STORED_TURNS = 40;
if (history.length > MAX_STORED_TURNS) {
  history.splice(0, history.length - MAX_STORED_TURNS);
}

return [{
  json: {
    success: true,
    sessionId,
    reply,
    timestamp: new Date().toISOString(),
  },
}];

const sessionId = $('Code - Construir historial').item.json.sessionId;

return [{
  json: {
    success: false,
    sessionId,
    error: 'No se pudo generar una respuesta en este momento. Intenta de nuevo en unos segundos.',
    code: 'PROVIDER_ERROR',
  },
}];

const code = $json.rateLimited ? 'RATE_LIMITED' : 'VALIDATION_ERROR';

return [{
  json: {
    success: false,
    error: $json.errorMessage,
    code,
  },
}];
